mapper.select:
SELECT pi."id", pd.id AS sku_id, pd.images_url, pi.spu_no, pd.sku_no, pd."name", pp.actual_arrival_qty, pp.arrival_state, pi.pirate_risk, pc.retail_price, pd.product_state, pd.create_user_id, pd.create_time, pi.spec_type FROM product_info pi INNER JOIN product_detail pd ON pi.id = pd.product_id LEFT JOIN product_purchase pp ON pp.sku_id = pd."id" LEFT JOIN product_cost pc ON pc.sku_id = pd."id" WHERE pi.delete_state = 0
AND (pi.spu_no LIKE concat('%',#{params.no},'%') OR pd.sku_no LIKE concat('%',#{params.no},'%'))
AND pd.product_state in
#{state}
AND pi.category_id=#{params.categoryId}
ORDER BY pd.create_time DESC

SELECT pi."id", pd.id AS sku_id, pd.images_url, pi.spu_no, pd.sku_no, pd."name", pp.actual_arrival_qty, pp.arrival_state, pi.pirate_risk, pc.retail_price, pd.product_state, pd.create_user_id, pd.create_time, pi.spec_type FROM product_info pi INNER JOIN product_detail pd ON pi.id = pd.product_id LEFT JOIN product_purchase pp ON pp.sku_id = pd."id" LEFT JOIN product_cost pc ON pc.sku_id = pd."id" WHERE pi.delete_state = 0
AND pi."name" = #{name}
AND pd.sku_no = #{skuNo}
LIMIT 1
